def building():
    # Original axonometric drawing with separated storeys and selectable systems.
    floors = ''
    for i in range(7):
        y = 130 + i*47
        floors += f'<g class="storey" style="--floor:{i}"><path d="M130 {y} 330 {y-85} 520 {y} 320 {y+89}Z" fill="url(#slab)"/><path d="M130 {y}v19l190 89v-19Z" fill="#183f4b" stroke="#40727b"/><path d="M320 {y+89} 520 {y}v19l-200 89Z" fill="#0b2631" stroke="#40727b"/>'
        for j in range(9):
            x=146+j*19
            floors += f'<path d="M{x} {y+13+j*0.48:.1f}v10" stroke="#76d8d0" opacity=".6"/>'
        floors += '</g>'
    return f'''<div class="building-stage" data-tilt><div class="stage-grid"></div><svg class="building-svg" viewBox="0 0 650 640" role="img" aria-label="Ilustrație axonometrică originală a unei clădiri cu șapte niveluri"><defs><linearGradient id="slab" x2="1" y2="1"><stop stop-color="#326b72"/><stop offset="1" stop-color="#0b2631"/></linearGradient><filter id="glow"><feGaussianBlur stdDeviation="3"/></filter></defs><ellipse cx="325" cy="565" rx="250" ry="45" fill="#51e4cf" opacity=".04"/>{floors}<g class="system-lines" fill="none" stroke="#73ffe1" stroke-width="2"><path d="M220 150v310l100 48 100-45V205"/><path d="m140 365 180 85 193-84" stroke-dasharray="5 6"/></g><path class="scan-plane" d="m112 290 215-91 212 92-217 99Z" fill="#5bffd7" opacity=".12" stroke="#70ffdc"/><g fill="#a1ffe9"><circle cx="220" cy="290" r="5"/><circle cx="420" cy="365" r="5"/><circle cx="320" cy="451" r="5"/></g><path d="m75 560 250 65 255-70" fill="none" stroke="#2d5359" stroke-dasharray="3 6"/></svg><div class="building-label label-top"><i></i><span>IDENTITATE DIGITALĂ<b>Hotel Meridian / Corp A</b></span></div><div class="building-label label-bottom"><span class="tiny-icon">↳</span><span>FIECARE NIVEL, CONECTAT<b data-layer-label>Instalații · Istoric · Documente</b></span></div><span class="stage-caption">VIZUALIZARE CONCEPTUALĂ · DATE DEMONSTRATIVE</span></div>'''

